# Generated by build.py from recipe.yml for recipe ftp-list-and-upload. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'site/sub', 'other' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/sub/a.txt'), "a`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/.hidden'), "not for you`n")
[IO.File]::WriteAllText((Join-Path $PWD 'notes.txt'), "uploaded by curl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'other/readme.txt'), "read me`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-anonymous', '--list-directories', '--allow-uploads', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -l ftp://127.0.0.1:8080/ } finally { Stop-Process $server0 }
